"""Expected results, generated by running reference scripts in the sandbox (R-EV-3).

``data/expected.json`` is never edited by hand. Each entry records the SHA-256 of the reference
script it came from, so a test can detect a reference that changed without regenerating.
"""

from __future__ import annotations

import hashlib
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from simagent.evaluation.tasks import Task
from simagent.runners.base import Runner
from simagent.runners.docker import DockerRunner

REFERENCE_TIMEOUT_S = 300.0


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def build_expected(tasks: list[Task], root: Path, runner: Runner) -> dict[str, Any]:
    """Run every ``.py`` reference in the Docker sandbox; raise if any fails."""
    if not isinstance(runner, DockerRunner):
        raise ValueError("expected values must be generated in the Docker sandbox")
    entries: dict[str, Any] = {}
    for task in tasks:
        if not task.runs_reference:
            continue
        path = root / task.reference
        res = runner.run(path.read_text(encoding="utf-8"), timeout_s=REFERENCE_TIMEOUT_S)
        if not res.ok:
            raise RuntimeError(f"reference for {task.id} failed: {res.failure}\n{res.stderr}")
        entries[task.id] = {
            "reference": task.reference,
            "reference_sha256": sha256(path),
            "result": res.result_json,
            "duration_s": round(res.duration_s, 3),
        }
    return {
        "description": "Generated by scripts/make_expected.py; do not edit by hand.",
        "generated_utc": datetime.now(UTC).isoformat(timespec="seconds"),
        "runner": "docker",
        "tasks": entries,
    }


def load_expected(path: Path) -> dict[str, Any]:
    data: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))
    return data


def write_expected(path: Path, data: dict[str, Any]) -> None:
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8", newline="\n")
